#pragma once
#include <stdint.h>
#include "IGantry.h"
#include "Magnet.h"
#include "Params.h"
#include "Path.h"

class FastAccelStepper;

// XY stage under the board: two A4988-driven steppers through FastAccelStepper
// (pulses generated by hardware). X follows the column, Y follows the row.
//
// Coordinates: the home position (both limit switches) is the centre of
// square (HOME_ROW, HOME_COL) = (-1, 0), i.e. the first reserve square on the
// machine side. Square (r, c) is at
//   x = (c - HOME_COL) * SQUARE_MM,  y = (r - HOME_ROW) * SQUARE_MM.
// Targets are clamped to rows -1..n and columns 0..n-1.
//
// travelTo follows travelPath one segment at a time at Params::freeSpeed;
// dragTo moves straight to a neighbouring square at Params::dragSpeed. Within
// a segment both axes start together with speeds and accelerations scaled to
// the segment direction, so the head moves along a straight line.
class Gantry : public IGantry {
 public:
  static constexpr float STEPS_PER_MM = 80.0f;  // GT2 20T, 200 step/rev, 1/16
  static constexpr float SQUARE_MM = 33.3f;
  static constexpr float HOME_ROW = -1.0f;
  static constexpr float HOME_COL = 0.0f;
  // PROVISIONAL: tune on the stage.
  static constexpr float ACCEL_MMS2 = 1500.0f;
  static constexpr float HOMING_MMS = 20.0f;
  static constexpr float HOMING_BACKOFF_MM = 3.0f;
  // Limit switch never reached within this travel: homing fails.
  static constexpr float HOMING_MAX_MM = 400.0f;

  Gantry(Magnet& magnet, const Params& p, int n);

  // Connects the steppers (FastAccelStepperEngine must already be init()ed
  // by begin) and the limit-switch inputs. False when a stepper cannot be
  // connected.
  bool begin();
  void setParams(const Params& p) { params_ = p; }
  // Drives both axes towards their limit switches, backs off, and defines the
  // position as (HOME_ROW, HOME_COL). Blocking. False on timeout or when the
  // steppers are not connected.
  bool home();
  bool homed() const { return homed_; }

  void travelTo(float r, float c) override;
  void dragTo(int r, int c) override;
  void magnet(MagnetMode m) override { magnet_.set(m); }
  bool idle() const override;
  float headR() const override;
  float headC() const override;
  void update(uint32_t now) override;

 private:
  bool startSegment(float toR, float toC, float speed);
  bool homeAxis(FastAccelStepper* s, uint8_t limitPin);
  float clampR(float r) const;
  float clampC(float c) const;

  Magnet& magnet_;
  Params params_;
  int n_;
  FastAccelStepper* x_ = nullptr;
  FastAccelStepper* y_ = nullptr;
  bool homed_ = false;
  float ptR_[TRAVEL_MAX_POINTS], ptC_[TRAVEL_MAX_POINTS];
  int ptCount_ = 0;
  int nextPt_ = 0;     // index of the next point to head for
  float speed_ = 1.0f; // squares/s of the current motion
};
